<template><div><h1 class="page-title">课程看板</h1><p class="page-desc">汇总文档入库、问答质量、引用率和反馈数据。</p><div v-if="!auth.hasCourse" class="empty-state">请先选择课程。</div><template v-else><el-button type="primary" :loading="loading" @click="load">刷新课程看板</el-button><div v-if="data" class="grid grid-3 dashboard-grid"><div class="kpi"><div class="label">文档总数</div><div class="value">{{ data.document_count || 0 }}</div></div><div class="kpi"><div class="label">成功入库</div><div class="value">{{ data.success_document_count || 0 }}</div></div><div class="kpi"><div class="label">入库失败</div><div class="value">{{ data.failed_document_count || 0 }}</div></div><div class="kpi"><div class="label">问答总数</div><div class="value">{{ data.qa_count || 0 }}</div></div><div class="kpi"><div class="label">无引用问题</div><div class="value">{{ data.no_citation_count || 0 }}</div></div><div class="kpi"><div class="label">低质量问题</div><div class="value">{{ data.low_quality_count || 0 }}</div></div><div class="kpi"><div class="label">引用率</div><div class="value">{{ ((data.citation_rate || 0) * 100).toFixed(1) }}%</div></div><div class="kpi"><div class="label">点赞数</div><div class="value">{{ data.feedback_up_count || 0 }}</div></div><div class="kpi"><div class="label">点踩数</div><div class="value">{{ data.feedback_down_count || 0 }}</div></div></div><div v-else class="empty-state dashboard-empty">点击“刷新课程看板”查看课程数据。</div></template></div></template>
<script setup>
import { ref } from 'vue'; import { ElMessage } from 'element-plus'; import { courseApi } from '../api'; import { errorMessage } from '../api/request'; import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(); const loading=ref(false); const data=ref(null)
async function load(){ loading.value=true; try{ const res=await courseApi.dashboard(auth.currentCourseId); data.value=res.data }catch(e){ ElMessage.error(errorMessage(e)) }finally{ loading.value=false } }
</script>
<style scoped>.dashboard-grid{margin-top:18px}.dashboard-empty{margin-top:18px}</style>
